{{
    config(
        materialized="table",
        schema="silver_noaa",
    )
}}

-- generated by det scaffold-dbt; silver identity/order from pipeline dbt.silver
with base as (
    select *
    from {{ ref("stg_noaa__fatalities") }}
),
deduped as (
    {{ det_dedupe_latest_run(
        "base",
        partition_by=["__row_hash"],
        order_by=["__extract_run_datetime desc"]
    ) }}
)
select
    deduped.*,
    current_timestamp as __silver_processed_at,
    current_timestamp as __silver_updated_at
from deduped
